//! Cargo-driven `netlogon.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is netlogon-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-kernel.json", "_DllMainCRTStartup@12", Some(0x70110000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7feba000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7feba000000u64)),
        o => panic!("netlogon-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/libwine/libwine.a", "sdk/lib/pseh/libpseh.a", "sdk/lib/crt/libchkstk.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/libwine/libwine.a", "sdk/lib/pseh/libpseh.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/libwine/libwine.a", "sdk/lib/pseh/libpseh.a", "sdk/lib/crt/libchkstk.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("netlogon-rust")
        .c_from_compile_db("netlogon_shims", &["base/services/netlogon/netlogon_s.c"])
        .resource_from_rc("base/services/netlogon/netlogon.rc", "netlogon_res")
        .spec2def("base/services/netlogon/netlogon.spec", "netlogon.dll")
        .spec_stubs()
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
